// Tool: search-emails
// Advanced email search using Gmail query syntax
import { isSensitiveText } from '../../helpers';
import { gmailFetch } from '../api/index';
import { upsertEmail } from '../db/helpers';
import { getGmailSkillState } from '../state';
import type { GmailMessage } from '../types';

export const searchEmailsTool: ToolDefinition = {
  name: 'search-emails',
  description:
    'Search emails using advanced Gmail query syntax. Supports complex queries with operators like from:, to:, subject:, has:attachment, is:unread, etc.',
  input_schema: {
    type: 'object',
    properties: {
      query: {
        type: 'string',
        description:
          'Gmail search query (e.g., "from:john@example.com subject:meeting is:unread", "has:attachment after:2023/01/01")',
      },
      max_results: {
        type: 'number',
        description: 'Maximum number of results to return (default: 20, max: 100)',
        minimum: 1,
        maximum: 100,
      },
      include_spam_trash: {
        type: 'boolean',
        description: 'Include results from spam and trash folders (default: false)',
      },
      page_token: { type: 'string', description: 'Token for pagination (from previous search)' },
    },
    required: ['query'],
  },
  async execute(args: Record<string, unknown>): Promise<string> {
    try {
      const query = args.query as string;
      if (!query) {
        return JSON.stringify({ success: false, error: 'Search query is required' });
      }

      // Build API parameters
      const params: string[] = [];
      params.push(`q=${encodeURIComponent(query)}`);

      const maxResults = Math.min(parseInt((args.max_results as string) || '20', 10), 100);
      params.push(`maxResults=${maxResults}`);

      if (args.include_spam_trash) {
        params.push('includeSpamTrash=true');
      }

      if (args.page_token) {
        params.push(`pageToken=${encodeURIComponent(args.page_token as string)}`);
      }

      // Search messages
      const searchResponse = await gmailFetch<{
        messages?: Array<{ id: string; threadId: string }>;
        nextPageToken?: string;
        resultSizeEstimate: number;
      }>(`/users/me/messages?${params.join('&')}`);

      if (!searchResponse.success || !searchResponse.data) {
        return JSON.stringify({
          success: false,
          error: searchResponse.error?.message || 'Search failed',
        });
      }

      const searchResults = searchResponse.data;

      if (!searchResults.messages || searchResults.messages.length === 0) {
        return JSON.stringify({
          success: true,
          emails: [],
          query,
          total_estimate: searchResults.resultSizeEstimate || 0,
          next_page_token: null,
        });
      }

      // Get detailed information for found emails
      const emails = [];
      const batchSize = 10; // Process in batches to avoid rate limits

      for (let i = 0; i < searchResults.messages.length; i += batchSize) {
        const batch = searchResults.messages.slice(i, i + batchSize);

        for (const msgRef of batch) {
          const msgResponse = await gmailFetch<GmailMessage>(
            `/users/me/messages/${msgRef.id}?format=metadata`
          );

          if (msgResponse.success && msgResponse.data) {
            const message = msgResponse.data as GmailMessage;
            const headers = message.payload?.headers || [];

            // Extract key headers
            const headerMap: Record<string, string> = {};
            headers.forEach((header: any) => {
              headerMap[header.name.toLowerCase()] = header.value;
            });

            // Parse sender info
            const from = headerMap.from || '';
            const fromMatch = from.match(/(.+?)\s*<([^>]+)>/) || [null, from, from];
            const senderName = fromMatch[1]?.trim().replace(/^["']|["']$/g, '') || null;
            const senderEmail = fromMatch[2]?.trim() || from;

            emails.push({
              id: message.id,
              thread_id: message.threadId,
              subject: headerMap.subject || '',
              sender: { email: senderEmail, name: senderName },
              recipients: headerMap.to || '',
              date: headerMap.date
                ? new Date(headerMap.date).toISOString()
                : new Date(parseInt(message.internalDate)).toISOString(),
              snippet: message.snippet,
              label_ids: message.labelIds || [],
              size_estimate: message.sizeEstimate || 0,
              status: {
                is_read: !message.labelIds?.includes('UNREAD'),
                is_important: message.labelIds?.includes('IMPORTANT'),
                is_starred: message.labelIds?.includes('STARRED'),
                has_attachments: hasAttachments(message),
              },
              relevance_score: calculateRelevanceScore(message, query),
            });

            // Cache in local database
            upsertEmail(message);
          }
        }

        // Small delay between batches to respect rate limits
        if (i + batchSize < searchResults.messages.length) {
          // In a real implementation, we might want to add a small delay here
          // but since we're in a synchronous environment, we'll continue
        }
      }

      // Filter out sensitive emails unless user opted in to show them
      const s = getGmailSkillState();
      const showSensitive = s.config.showSensitiveMessages ?? false;
      const filteredEmails = showSensitive
        ? emails
        : emails.filter(
            (e: { subject?: string; snippet?: string }) =>
              !isSensitiveText((e.subject || '') + ' ' + (e.snippet || ''))
          );

      // Sort by relevance score (highest first)
      filteredEmails.sort((a, b) => b.relevance_score - a.relevance_score);

      return JSON.stringify({
        success: true,
        emails: filteredEmails,
        query,
        total_estimate: searchResults.resultSizeEstimate,
        returned_count: filteredEmails.length,
        next_page_token: searchResults.nextPageToken || null,
        search_tips: generateSearchTips(query),
      });
    } catch (error) {
      return JSON.stringify({
        success: false,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  },
};

/**
 * Helper: Check if message has attachments
 */
function hasAttachments(message: any): boolean {
  if (message.payload?.body?.attachmentId) return true;
  if (message.payload?.parts) {
    return message.payload.parts.some(
      (part: any) => part.body?.attachmentId || (part.filename && part.filename.length > 0)
    );
  }
  return false;
}

/**
 * Helper: Calculate relevance score based on query matching
 */
function calculateRelevanceScore(message: any, query: string): number {
  let score = 0;
  const queryLower = query.toLowerCase();

  // Check subject relevance
  const subject =
    message.payload?.headers?.find((h: any) => h.name.toLowerCase() === 'subject')?.value || '';
  if (subject.toLowerCase().includes(queryLower)) {
    score += 10;
  }

  // Check snippet relevance
  if (message.snippet?.toLowerCase().includes(queryLower)) {
    score += 5;
  }

  // Boost score for unread messages
  if (message.labelIds?.includes('UNREAD')) {
    score += 3;
  }

  // Boost score for important messages
  if (message.labelIds?.includes('IMPORTANT')) {
    score += 5;
  }

  // Boost score for recent messages
  const messageDate = new Date(parseInt(message.internalDate));
  const daysSinceMessage = (Date.now() - messageDate.getTime()) / (1000 * 60 * 60 * 24);
  if (daysSinceMessage < 7) {
    score += 2;
  }

  return score;
}

/**
 * Helper: Generate search tips based on the query
 */
function generateSearchTips(query: string): string[] {
  const tips: string[] = [];

  if (!query.includes(':')) {
    tips.push('Use operators like "from:", "to:", "subject:" for more precise searches');
  }

  if (!query.includes('has:')) {
    tips.push('Use "has:attachment" to find emails with attachments');
  }

  if (!query.includes('is:')) {
    tips.push('Use "is:unread", "is:important", or "is:starred" to filter by status');
  }

  if (!query.includes('after:') && !query.includes('before:')) {
    tips.push('Use "after:2023/01/01" or "before:2023/12/31" to filter by date');
  }

  if (!query.includes('label:')) {
    tips.push('Use "label:inbox" or "label:sent" to search within specific labels');
  }

  return tips.slice(0, 3); // Return max 3 tips
}

// Notion Databases API
import type {
  CreateDatabaseResponse,
  GetDatabaseResponse,
  GetDataSourceResponse,
  QueryDataSourceResponse,
  SearchResponse,
  UpdateDatabaseResponse,
} from '@notionhq/client/build/src/api-endpoints';

import {
  detectApiVersion,
  formatApiError,
  getQueryEndpoint,
  resolveDataSourceId,
} from '../helpers';
import { apiFetch } from './client';

export function getDatabase(databaseId: string): Promise<GetDatabaseResponse> {
  return apiFetch<GetDatabaseResponse>(`/databases/${databaseId}`);
}

/**
 * Resolve a database container ID to its first data_source ID.
 * This is needed because the Notion API 2025-09-03 uses data_sources
 * for queries and schema access. Now uses the helper function for better compatibility.
 */
export async function resolveDataSourceIdCompat(databaseId: string): Promise<string> {
  try {
    return await resolveDataSourceId(databaseId);
  } catch (error) {
    throw new Error(
      `Database has no data sources or is not accessible. Share the database with your integration. ${formatApiError(error)}`
    );
  }
}

export function getDataSource(dataSourceId: string): Promise<GetDataSourceResponse> {
  return apiFetch<GetDataSourceResponse>(`/data_sources/${dataSourceId}`);
}

/**
 * Query a database with automatic API version detection and endpoint resolution.
 * Handles both legacy database queries and new data source queries seamlessly.
 * Provides automatic fallback for maximum compatibility.
 */
export async function queryDataSource(
  databaseId: string,
  body?: Record<string, unknown>
): Promise<QueryDataSourceResponse> {
  const apiVersion = await detectApiVersion();
  const requestBody = body || {};

  try {
    // Get the appropriate endpoint for the current API version
    const endpoint = await getQueryEndpoint(databaseId);

    console.log(`[notion][databases] Querying ${endpoint} with API version ${apiVersion}`);

    return await apiFetch<QueryDataSourceResponse>(endpoint, {
      method: 'POST',
      body: requestBody,
      apiVersion,
    });
  } catch (error) {
    const errorMessage = String(error);

    // If new API fails with version/endpoint errors, try legacy fallback
    if (
      apiVersion !== '2022-06-28' &&
      (errorMessage.includes('invalid_version') ||
        errorMessage.includes('data_source') ||
        errorMessage.includes('404'))
    ) {
      console.log(
        `[notion][databases] New API failed, attempting legacy fallback for database ${databaseId}`
      );

      try {
        return await apiFetch<QueryDataSourceResponse>(`/databases/${databaseId}/query`, {
          method: 'POST',
          body: requestBody,
          apiVersion: '2022-06-28',
        });
      } catch (fallbackError) {
        console.error(`[notion][databases] Legacy fallback also failed:`, fallbackError);
        throw new Error(
          `Failed to query database with both new and legacy APIs: ${formatApiError(fallbackError)}`
        );
      }
    }

    // Re-throw the original error if it's not a version-related issue
    throw error;
  }
}

/**
 * Create a database with API version compatibility.
 */
export async function createDatabase(
  body: Record<string, unknown>
): Promise<CreateDatabaseResponse> {
  const apiVersion = await detectApiVersion();
  return apiFetch<CreateDatabaseResponse>('/databases', { method: 'POST', body, apiVersion });
}

/**
 * Update a database with API version compatibility.
 */
export async function updateDatabase(
  databaseId: string,
  body: Record<string, unknown>
): Promise<UpdateDatabaseResponse> {
  const apiVersion = await detectApiVersion();
  return apiFetch<UpdateDatabaseResponse>(`/databases/${databaseId}`, {
    method: 'PATCH',
    body,
    apiVersion,
  });
}

/**
 * List all databases with API version compatibility.
 * Uses data_source filter for new API, database filter for legacy API.
 */
export async function listAllDatabases(pageSize: number = 20): Promise<SearchResponse> {
  const apiVersion = await detectApiVersion();

  // Use appropriate filter based on API version
  const filter =
    apiVersion === '2025-09-03'
      ? { property: 'object', value: 'data_source' }
      : { property: 'object', value: 'database' };

  try {
    return await apiFetch<SearchResponse>('/search', {
      method: 'POST',
      body: { filter, page_size: pageSize },
      apiVersion,
    });
  } catch (error) {
    // If new API search fails, try legacy database search
    if (apiVersion !== '2022-06-28') {
      console.log(`[notion][databases] New API search failed, trying legacy database search`);
      return await apiFetch<SearchResponse>('/search', {
        method: 'POST',
        body: { filter: { property: 'object', value: 'database' }, page_size: pageSize },
        apiVersion: '2022-06-28',
      });
    }
    throw error;
  }
}

