  ensureValidToken,
  storeTokens,
} from './oauth';

// Notion Comments API
import type {
  CreateCommentResponse,
  ListCommentsResponse,
} from '@notionhq/client/build/src/api-endpoints';

import { apiFetch } from './client';

export function createComment(body: Record<string, unknown>): Promise<CreateCommentResponse> {
  return apiFetch<CreateCommentResponse>('/comments', { method: 'POST', body });
}

export function listComments(
  blockId: string,
  pageSize: number = 20
): Promise<ListCommentsResponse> {
  return apiFetch<ListCommentsResponse>(`/comments?block_id=${blockId}&page_size=${pageSize}`);
}

// Notion Users API
import type { GetUserResponse, ListUsersResponse } from '@notionhq/client/build/src/api-endpoints';

import { apiFetch } from './client';

export function getUser(userId: string): Promise<GetUserResponse> {
  return apiFetch<GetUserResponse>(`/users/${userId}`);
}

export function listUsers(pageSize: number = 20, startCursor?: string): Promise<ListUsersResponse> {
  let endpoint = `/users?page_size=${pageSize}`;
  if (startCursor) endpoint += `&start_cursor=${startCursor}`;
  return apiFetch<ListUsersResponse>(endpoint);
}

// Centralized Notion API fetch resolver.
import { notionFetch } from '../helpers';

export async function apiFetch<T>(
  endpoint: string,
  options?: { method?: string; body?: unknown; apiVersion?: string }
): Promise<T> {
  return await notionFetch<T>(endpoint, options);
}

// Notion Search API — POST /v1/search with query, filter, sort, page_size
import type { SearchResponse } from '@notionhq/client/build/src/api-endpoints';

import { apiFetch } from './client';

export interface SearchRequest {
  query?: string;
  filter?: { property: string; value: string };
  sort?: { direction: 'ascending' | 'descending'; timestamp: 'last_edited_time' };
  page_size?: number;
  start_cursor?: string;
}

export function search(body: SearchRequest | Record<string, unknown>): Promise<SearchResponse> {
  return apiFetch<SearchResponse>('/search', { method: 'POST', body });
}
